const req = $('When Executed by Another Workflow').first().json;
const draft = $('Get Draft').first().json;
const version = $input.first().json;
if (!draft.id) throw new Error('draft_not_found');
if (Number(req.version) !== Number(draft.current_version)) throw new Error('stale_version: version mới nhất là ' + draft.current_version);
if (['publishing', 'published', 'partial_failure'].includes(draft.status)) throw new Error('draft_already_published');
const stop = (status, message) => [{ json: { allowed: false, result: { status, draft_id: draft.id, version: Number(req.version), message } } }];
// Xác nhận chỉ lấy từ tin nhắn thật của admin ở lượt này (main workflow gắn cố định, model không điền được).
const text = String(req.confirmation_text || '').normalize('NFC').toLowerCase();
const L = '(?<![\\p{L}\\p{N}_])';
const R = '(?![\\p{L}\\p{N}_])';
const words = '(?:phê duyệt|duyệt|chốt|đồng ý|xác nhận|approve|approved|ok|okay|oke)';
const confirmRe = new RegExp(L + words + R, 'u');
const negatedRe = new RegExp(L + '(?:đừng|chớ|chưa|không|khoan|hủy|huỷ|bỏ|dừng|don\'t|do not|not|never|cancel)\\s+(?:được\\s+|nên\\s+|cần\\s+|vội\\s+|phải\\s+)*' + words + R, 'u');
if (!confirmRe.test(text) || negatedRe.test(text)) {
  return stop('needs_admin_confirmation', 'Tin nhắn hiện tại của admin chưa xác nhận duyệt rõ ràng (ví dụ "chốt bản này", "duyệt"). Hãy cho admin đọc bản nháp, hỏi họ có duyệt không rồi chờ tin nhắn xác nhận của họ. Không tự duyệt.');
}
// Bản nháp phải có trước khi lượt chat này bắt đầu: admin chưa thể đã đọc bản vừa tạo/sửa trong chính lượt này.
const turnMs = Date.parse(req.turn_started_at);
if (Number.isNaN(turnMs)) throw new Error('turn_started_at_missing: không xác định được thời điểm bắt đầu lượt chat nên không thể duyệt');
if (!version.id) throw new Error('version_not_found');
const createdMs = Date.parse(version.created_at);
const SKEW_MS = 5000; // dung sai lệch đồng hồ n8n/Supabase, nghiêng về phía từ chối
if (Number.isNaN(createdMs) || createdMs >= turnMs - SKEW_MS) {
  return stop('needs_admin_review', 'Bản nháp vừa được tạo/sửa ở lượt này; hãy cho admin đọc rồi chờ họ xác nhận ở tin nhắn sau.');
}
return [{ json: { allowed: true, ...req } }];
